    private void filmProfileRow(UtilitySheet sheet,JSONObject j){LinearLayout card=a.row();card.setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(10));card.setBackground(a.bg(PANEL,16,tone(AppTheme.BORDER)));ImageView cover=new ImageView(a);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setImageDrawable(new LabelCover(j));a.add(card,cover,116,76);if(!j.optString("cover").isEmpty())thumb(cover,new File(new File(a.getFilesDir(),"covers"),new File(j.optString("cover")).getName()),j.optString("id",j.optString("name")));LinearLayout labels=a.column();labels.setPadding(a.dp(12),0,0,0);TextView name=a.text(j.optString("name"),15,CREAM);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);a.add(labels,name,-1,-2);TextView type=a.text(profileCaption(j),12,MUTED);type.setMaxLines(2);a.add(labels,type,-1,-2);card.addView(labels,new LinearLayout.LayoutParams(0,-2,1));card.setContentDescription(j.optString("name")+"，"+profileCaption(j));card.setFocusable(true);card.setOnClickListener(v->{sheet.dismiss();filmProfileActions(j);});a.add(sheet.content,card,-1,Math.max(104,Math.round(60+36*a.getResources().getConfiguration().fontScale)));a.gap(sheet.content,10);}
    private static String profileCaption(JSONObject j){int iso=j.optInt("nominal_iso",0);return j.optString("type","彩色")+(iso>0?" · ISO "+iso:" · 色彩灵感配方");}
    JSONObject filmData(int stock){stock=FilmCatalog.safe(stock);if(stock>=51){FilmLabelStyle label=FilmLabelStyle.of(stock);return RollRepository.object("name",FilmCatalog.NAMES[stock],"stock",stock,"nominal_iso",label.iso(),"type",label.type().equals("MONOCHROME")?"黑白":label.type().equals("REVERSAL")?"反转片":"彩色","temperature",0);}String name=FilmCatalog.NAMES[FilmCatalog.safe(stock)];int nominal=400;java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?<!\\d)(\\d{2,4})(?!\\d)").matcher(name);if(m.find())try{nominal=Integer.parseInt(m.group(1));}catch(Exception ignored){}return RollRepository.object("name",name,"stock",stock,"nominal_iso",nominal,"type",name.contains("黑白")||name.contains("硬黑")||name.contains("HP5")||name.contains("棕片")?"黑白":name.contains("反转")||name.contains("正片")||name.contains("Kodachrome")?"反转片":"彩色","temperature",0);}
    void filmDetails(int stock){filmProfileActions(filmData(stock));}
