    void annotate(String id){a.worker.execute(()->{JSONObject item=studio.repository.find("items",id);if(item==null)item=a.readMeta(id);final JSONObject record=item;a.main.post(()->a.openUtility(new UtilitySheet(a,"档案与补填",s->{JSONObject previous=record.optJSONObject("annotations");if(previous==null)previous=new JSONObject();s.note("原始 EXIF 与手机实际参数保留；下方内容是独立补填记录，不回写原片。");EditText camera=StudioUi.field(a,s,"相机",previous.optString("camera"),false),lens=StudioUi.field(a,s,"镜头",previous.optString("lens"),false),iso=StudioUi.field(a,s,"ISO / EI，可留空",previous.optString("iso"),true),f=StudioUi.field(a,s,"光圈，可留空",previous.optString("aperture"),true),t=StudioUi.field(a,s,"快门秒，可留空",previous.optString("seconds"),true),date=StudioUi.field(a,s,"拍摄日期 yyyy:MM:dd HH:mm:ss，可留空",previous.optString("date"),false),notes=StudioUi.field(a,s,"备注",previous.optString("notes"),false);s.action("保存补填",()->{try{JSONObject data=RollRepository.object("camera",camera.getText().toString(),"lens",lens.getText().toString(),"notes",notes.getText().toString());for(EditText e:new EditText[]{iso,f,t})if(e.length()>0)StudioUi.number(e,.000001,1000000);if(iso.length()>0)data.put("iso",iso.getText().toString());if(f.length()>0)data.put("aperture",f.getText().toString());if(t.length()>0)data.put("seconds",t.getText().toString());if(date.length()>0){if(!PrintMetadata.validDate(date.getText().toString()))throw new IllegalArgumentException("拍摄日期格式无效");data.put("date",date.getText().toString());}s.dismiss();StudioUi.work(a,()->studio.repository.annotate(id,data),()->{a.toast("补填已保存");if(a.page==2)render();});}catch(Exception e){a.toast(e.getMessage());}});s.action("移动到其他胶卷",()->{s.dismiss();chooseRoll(false,r->StudioUi.work(a,()->studio.repository.move(Collections.singletonList(id),r.optString("id")),()->{if(a.page==2)render();}));});if(NegativeStore.valid(id))s.action("原件导出",()->{s.dismiss();studio.media.originals(Collections.singletonList(id));});})));});}
    private void meterDetail(JSONObject j){a.openUtility(new UtilitySheet(a,"测光记录",s->{s.note(String.format(Locale.US,"EV100 %.2f\n建议 f/%.1f · %s · EI %.0f\nND %.1f 档 · 补偿 %+.1f 档\n倒易率 %s\n\n原始手机元数据仅作为测光来源，以上为实体摄影建议。",j.optDouble("ev100"),j.optDouble("aperture"),MeterMath.time(j.optDouble("seconds")),j.optDouble("ei"),j.optDouble("nd"),j.optDouble("compensation"),j.optString("reciprocity")));if(!j.optString("reference").isEmpty()){ImageView im=new ImageView(a);im.setScaleType(ImageView.ScaleType.FIT_CENTER);a.add(s.content,im,-1,220);thumb(im,new File(new File(a.getFilesDir(),"meter-references"),new File(j.optString("reference")).getName()),j.optString("id"));}s.action("备注与补填",()->{s.dismiss();annotate(j.optString("id"));});s.action("导出所属胶卷 CSV",()->{s.dismiss();studio.media.csv(j.optString("roll_id"));});}));}
